<?php
// Independent PUBLIC signed group/profile and current-author decision subset.
declare(strict_types=1);
$checks=0;function must(bool $v):void{global $checks;++$checks;if(!$v)throw new RuntimeException('V1_AUTHORITY_FIXTURE_MISMATCH');}
function un64(string $v):string{return base64_decode(strtr($v,'-_','+/'),true);}
function b64(string $v):string{return rtrim(strtr(base64_encode($v),'+/','-_'),'=');}
function canonical(mixed $v):string{if(is_object($v)){$a=get_object_vars($v);foreach(array_keys($a)as$k)must(preg_match('/^[\x20-\x7e]+$/D',$k)===1);ksort($a,SORT_STRING);return '{'.implode(',',array_map(fn($k)=>json_encode($k).':'.canonical($a[$k]),array_keys($a))).'}';}if(is_array($v))return '['.implode(',',array_map('canonical',$v)).']';must(!is_float($v));return json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}
function hashRecord(string $kind,object $record):string{return b64(hash('sha256',"AnyNote/p02-group-c2/hash/$kind\0".canonical($record),true));}
$f=json_decode(file_get_contents($argv[1]),false,32,JSON_THROW_ON_ERROR);$o=$f->objects;$e=$o->evidence;$accounts=[];
foreach($e->accounts as$a){$body=$a->identity->body;must(sodium_crypto_sign_verify_detached(un64($a->identity->signature),"AnyNote/p02-identity-c1/sign/account-root-identity\0".canonical($body),un64($body->root_signing_key)));must(b64(hash('sha256',"AnyNote/p02-identity-c1/hash/account-root-identity\0".canonical($body),true))===$a->pin->root_fingerprint);$event=$a->events[0];must($event->body->kind==='register');must(sodium_crypto_sign_verify_detached(un64($event->signature),"AnyNote/p02-state-c1/sign/device-roster-event\0".canonical($event->body),un64($body->root_signing_key)));$cert=$event->body->payload->certificate;must(sodium_crypto_sign_verify_detached(un64($cert->signature),"AnyNote/p02-identity-c1/sign/provisional-device-certificate\0".canonical($cert->body),un64($body->root_signing_key)));$accounts[$body->account_id]=['cert'=>$cert,'root'=>$a->pin->root_fingerprint,'roster'=>(object)['version'=>$event->body->version,'digest'=>b64(hash('sha256',"AnyNote/p02-state-c1/hash/event\0".canonical($event),true))]];}
function verifyGroup(object $r,array $accounts):void{$s=$r->body->signer??$r->body->intent->body->signer;must(isset($accounts[$s->account_id]));$a=$accounts[$s->account_id];must($s->root_fingerprint===$a['root']&&canonical($s->roster_head)===canonical($a['roster']));must(sodium_crypto_sign_verify_detached(un64($r->signature),"AnyNote/p02-group-c2/sign/{$r->body->purpose}\0".canonical($r->body),un64($a['cert']->body->device_signing_key)));}
$ev=$e->groups[0];$pin=$o->kit->independent_group_pins[0];must(hashRecord('policy',$ev->genesis)===$pin->genesis_digest);verifyGroup($ev->genesis,$accounts);$members=$ev->genesis->body->members;$policy=(object)['version'=>'0','digest'=>hashRecord('policy',$ev->genesis)];$epoch=null;
foreach($ev->transitions as$step){must($step->kind==='epoch');$c=$step->value->record;verifyGroup($c,$accounts);verifyGroup($c->body->intent,$accounts);verifyGroup($c->body->descriptor,$accounts);if($c->body->policy!==null){$p=$c->body->policy;verifyGroup($p,$accounts);must($p->body->action==='admit'&&canonical($p->body->predecessor)===canonical($policy));$members=$p->body->members;$policy=(object)['version'=>$p->body->version,'digest'=>hashRecord('policy',$p)];must(count($members)<=20&&count(array_filter($members,fn($m)=>$m->role==='owner'))===1);}
 $intent=$c->body->intent->body;must(canonical($intent->membership)===canonical($policy));$epoch=(object)['membership'=>$policy,'key_epoch'=>$intent->next_epoch,'epoch_digest'=>hashRecord('epoch-intent',$c->body->intent),'history_checkpoint_digest'=>null];
}
function decision(object $env,object $epoch,array $members,array $accounts):string{$c=$env->header->context;global $ev;if($c->service_id!==$ev->genesis_pin->service_id||$c->group_id!==$ev->genesis_pin->group_id)return 'GROUP_CONTEXT_MISMATCH';if(canonical($c->policy)!==canonical($epoch))return 'POLICY_OR_EPOCH_CHANGED';$a=$accounts[$c->author->account_id]??null;if(!$a)return 'PINNED_ACCOUNT_REQUIRED';$member=array_values(array_filter($members,fn($m)=>$m->account_id===$c->author->account_id&&$m->root_fingerprint===$c->author->root_fingerprint))[0]??null;if(!$member)return 'ACCESS_REVOKED';if($member->role==='reader')return 'WRITER_REQUIRED';if($c->object_kind==='group-metadata'&&$member->role!=='owner')return 'OWNER_REQUIRED';$cert=$a['cert']->body;if($cert->device_id!==$c->author->device_id||$cert->recovery_generation!==$c->author->recovery_generation||$a['root']!==$c->author->root_fingerprint||canonical($a['roster'])!==canonical($c->author->roster))return 'ROSTER_CHANGED';if(!sodium_crypto_sign_verify_detached(un64($env->signature),"AnyNote/p02-v1/sign/object-revision\0".canonical($env->header),un64($cert->device_signing_key)))return 'SIGNATURE_INVALID';return 'ACCEPT_CURRENT';}
foreach($o->authorization_cases as$case)must(decision($case->envelope,$epoch,$members,$accounts)===$case->expected);
echo json_encode(['status'=>'PASS','scope'=>'PUBLIC_C2_GROUP_CHAIN_CURRENT_AUTHOR_DECISION_SUBSET','checks'=>$checks,'decisions'=>count($o->authorization_cases),'members'=>count($members),'php'=>PHP_VERSION,'general_roster_revoke_SQL_and_freshness'=>'NOT_IMPLEMENTED'],JSON_THROW_ON_ERROR)."\n";
